    "C37","C38","C40","C41","C42","C43","C44","C48","C49","C50","C51","C52","C53","C55","C56","C57","C58","C59","C60"
  ],
  "contradictory_card_ids": ["C20","C23"],
  "prediction_basis_card_ids": [
    "C15","C06","C13","C01","C09","C22","C14","C16","C03","C04","C05","C10",
    "C40","C41","C43","C38","C44","C42","C50","C51","C55","C57","C59","C60","C58","C52"
  ],
  "claims": [
    {
      "claim": "Verapamil, the closest structural parent, has very high intestinal permeability: Caco-2 Papp 25.2×10^-6 cm/s and 68.9–156.6×10^-6 cm/s for R-verapamil, high BCS A-B permeability, and high pig jejunal P_eff; transport is mainly passive and P-gp efflux is a minor component.",
      "card_ids": ["C51","C55","C57","C59","C60","C49","C50"]
    },
    {
      "claim": "Intestinal CYP3A4 activity did not reduce verapamil permeability in Caco-2, and no L5 record shows gut-wall metabolism producing low F for verapamil-like compounds.",
      "card_ids": ["C50","C51"]
    },
    {
      "claim": "Other basic amines with high permeability support that ionization does not preclude absorption: imipramine Caco-2 permeability ~10^-5 cm/s with 100% human absorption, D-617 net Caco-2 permeability 16.9, and IS0042 readily penetrates Caco-2.",
      "card_ids": ["C58","C52","C56","C37","C48"]
    },
    {
      "claim": "Direct F measurements for verapamil and related analogs remain supportive: fasted verapamil F=22% (17–29%), SR verapamil 49±14% fasted and 34±12% fed, drotaverine 58.2±18.2%, bevantolol ~57–60%, and vernakalant 58–71%.",
      "card_ids": ["C15","C06","C13","C01","C09","C22","C14","C16"]
    },
    {
      "claim": "The only low-direction F evidence is gallopamil absolute/systemic F=15–23%, but gallopamil is a trimethoxy nitrile analog rather than the query's benzazepinone, and its L1 96.3% value is internally inconsistent; this is low-transferability and does not overturn the supportive direction.",
      "card_ids": ["C20","C23","C11"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C49","C50","C51","C52","C53","C55","C56","C57","C58","C59","C60"]
    },
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C54"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule itself.",
    "Query-specific gut-wall efflux, intestinal metabolism, and first-pass extraction are not experimentally measured.",
    "L5 records are mostly verapamil and imipramine data; the query's benzazepinone lactam and extra methoxy substitution may alter transporter or metabolic behavior.",
    "The gallopamil low-F value (15–23%) is unresolved against its internally inconsistent L1 96.3% value and is low-transferability to the query.",
    "Query formulation, dose, food state, and IV comparator are unspecified."
  ],
  "decision_summary": "Prediction remains high and is strengthened by L5: verapamil, the closest structural parent, shows very high passive permeability in Caco-2 and pig jejunum, transport dominated by passive diffusion, with P-gp efflux only a minor component and CYP3A4 not reducing permeability; imipramine and related basic amines also show high permeability. Combined with direct F values for verapamil (22% fasted; 34–49% SR) and analogs (drotaverine 58%, bevantolol ~57–60%, vernakalant 58–71%), F>=20% is better supported. Confidence remains moderate because no direct query F exists and gallopamil's low F (15–23%) is a low-transferability counterexample."
}

